mapper.sql:
FUNCTION source_text(p_owner VARCHAR2, p_name VARCHAR2, p_type VARCHAR2) RETURN CLOB IS
    result CLOB;
BEGIN
    FOR r IN (
        SELECT CASE WHEN line = 1 THEN REGEXP_REPLACE(text, ' {2,}', ' ') ELSE text END AS text
        FROM all_source WHERE owner = p_owner AND name = p_name AND type = p_type ORDER BY line
    ) LOOP
        IF result IS NULL THEN
            DBMS_LOB.CREATETEMPORARY(result, TRUE);
            DBMS_LOB.WRITEAPPEND(result, LENGTH('CREATE OR REPLACE '), 'CREATE OR REPLACE ');
        END IF;
        IF r.text IS NOT NULL THEN
            DBMS_LOB.WRITEAPPEND(result, LENGTH(r.text), r.text);
        END IF;
    END LOOP;
    RETURN result;
END;

FUNCTION long_value(p_query VARCHAR2, p1 VARCHAR2, p2 VARCHAR2, p3 VARCHAR2 DEFAULT NULL) RETURN CLOB IS
    cur INTEGER := DBMS_SQL.OPEN_CURSOR;
    buf VARCHAR2(32767);
    buf_len INTEGER;
    pos INTEGER := 0;
    result CLOB;
    ignore INTEGER;
BEGIN
    DBMS_SQL.PARSE(cur, p_query, DBMS_SQL.NATIVE);
    DBMS_SQL.BIND_VARIABLE(cur, ':p1', p1);
    DBMS_SQL.BIND_VARIABLE(cur, ':p2', p2);
    IF p3 IS NOT NULL THEN
        DBMS_SQL.BIND_VARIABLE(cur, ':p3', p3);
    END IF;
    DBMS_SQL.DEFINE_COLUMN_LONG(cur, 1);
    ignore := DBMS_SQL.EXECUTE(cur);
    IF DBMS_SQL.FETCH_ROWS(cur) > 0 THEN
        DBMS_LOB.CREATETEMPORARY(result, TRUE);
        LOOP
            DBMS_SQL.COLUMN_VALUE_LONG(cur, 1, 32767, pos, buf, buf_len);
            EXIT WHEN buf_len = 0;
            DBMS_LOB.WRITEAPPEND(result, LENGTH(buf), buf);
            pos := pos + buf_len;
        END LOOP;
    END IF;
    DBMS_SQL.CLOSE_CURSOR(cur);
    RETURN result;
END;

mapper.select:
WITH
ora_all_tables AS ( SELECT COALESCE(t1.OWNER, '') AS schema_name, 'table' AS table_type, COALESCE(REGEXP_REPLACE(tcom.COMMENTS, '\r|\n|\r\n', ''), '') AS logical_table_name, COALESCE(t1.TABLE_NAME, '') AS physical_table_name, NULL AS definition FROM ALL_TABLES t1 LEFT OUTER JOIN ALL_MVIEWS m ON t1.OWNER = m.OWNER AND t1.TABLE_NAME = m.MVIEW_NAME LEFT OUTER JOIN ALL_TAB_COMMENTS tcom ON t1.OWNER = tcom.OWNER AND t1.TABLE_NAME = tcom.TABLE_NAME WHERE m.MVIEW_NAME IS NULL AND t1.OWNER NOT IN
AND t1.OWNER IN
#{schema}
UNION ALL SELECT COALESCE(t2.OWNER, '') AS schema_name, 'view' AS table_type, COALESCE(REGEXP_REPLACE(vcom.COMMENTS, '\r|\n|\r\n', ''), '') AS logical_table_name, COALESCE(t2.VIEW_NAME, '') AS physical_table_name, long_value('SELECT text FROM all_views WHERE owner = :p1 AND view_name = :p2', t2.OWNER, t2.VIEW_NAME) AS definition FROM ALL_VIEWS t2 LEFT OUTER JOIN ALL_TAB_COMMENTS vcom ON t2.OWNER = vcom.OWNER AND t2.VIEW_NAME = vcom.TABLE_NAME WHERE t2.OWNER NOT IN
AND t2.OWNER IN
#{schema}
UNION ALL SELECT COALESCE(t3.OWNER, '') AS schema_name, 'materialized_view' AS table_type, COALESCE(REGEXP_REPLACE(mcom.COMMENTS, '\r|\n|\r\n', ''), '') AS logical_table_name, COALESCE(t3.MVIEW_NAME, '') AS physical_table_name, long_value('SELECT query FROM all_mviews WHERE owner = :p1 AND mview_name = :p2', t3.OWNER, t3.MVIEW_NAME) AS definition FROM ALL_MVIEWS t3 LEFT OUTER JOIN ALL_MVIEW_COMMENTS mcom ON t3.OWNER = mcom.OWNER AND t3.MVIEW_NAME = mcom.MVIEW_NAME WHERE t3.OWNER NOT IN
AND t3.OWNER IN
#{schema}
) SELECT SYS_CONTEXT('USERENV','DB_NAME') AS "dbName", schema_name AS "schemaName", logical_table_name AS "logicalTableName", physical_table_name AS "physicalTableName", table_type AS "tableType", definition AS definition, COALESCE(( SELECT pt.partitioning_type || ' (' || LISTAGG(k.column_name, ', ') WITHIN GROUP (ORDER BY k.column_position) || ')' FROM all_part_tables pt JOIN all_part_key_columns k ON k.owner = pt.owner AND k.name = pt.table_name AND k.object_type = 'TABLE' WHERE pt.owner = schema_name AND pt.table_name = physical_table_name AND table_type = 'table' GROUP BY pt.partitioning_type ), '') AS "partitionKey" FROM ora_all_tables ORDER BY schema_name, physical_table_name

WITH ora_all_constraints AS ( SELECT ac.owner AS schema_name, ac.table_name AS table_name, ac.constraint_name AS constraints_name, CASE ac.constraint_type WHEN 'C' THEN 'CHECK' WHEN 'R' THEN 'FOREIGN KEY' WHEN 'P' THEN 'PRIMARY KEY' WHEN 'U' THEN 'UNIQUE' ELSE NULL END AS constraints_type, CASE ac.constraint_type WHEN 'C' THEN 'CHECK (' || ac.search_condition_vc || ')' WHEN 'R' THEN 'FOREIGN KEY (' || LISTAGG(acc.column_name, ',') WITHIN GROUP (ORDER BY acc.position) || ') REFERENCES ' || ac_r.table_name || '(' || LISTAGG(acc_r.column_name, ',') WITHIN GROUP (ORDER BY acc.position) || ')' WHEN 'P' THEN 'PRIMARY KEY (' || LISTAGG(acc.column_name, ',') WITHIN GROUP (ORDER BY acc.position) || ')' WHEN 'U' THEN 'UNIQUE (' || LISTAGG(acc.column_name, ',') WITHIN GROUP (ORDER BY acc.position) || ')' ELSE NULL END AS constraints_definition FROM all_constraints ac LEFT OUTER JOIN all_cons_columns acc ON ac.constraint_name = acc.constraint_name AND ac.owner = acc.owner LEFT OUTER JOIN all_constraints ac_r ON ac.r_constraint_name = ac_r.constraint_name AND ac.r_owner = ac_r.owner LEFT OUTER JOIN all_cons_columns acc_r ON ac_r.constraint_name = acc_r.constraint_name AND ac_r.owner = acc_r.owner AND acc.position = acc_r.position WHERE ac.constraint_type IN ('C', 'R', 'P', 'U') /* 列のNOT NULLもCHECK制約として格納され、名前を付けなければ実行環境ごとに変わるSYS_C...の名前になる。 NOT NULLはカラム情報に出すため、制約としては出さない。 NOT NULLの条件は「"列名" IS NOT NULL」の形で格納される（CHECK句に書いた条件は書いたとおりに格納される） */ AND CASE WHEN ac.constraint_type = 'C' AND ac.search_condition_vc = '"' || acc.column_name || '" IS NOT NULL' THEN 1 ELSE 0 END = 0 AND ac.OWNER NOT IN
AND ac.owner IN
#{schema}
AND ac.table_name IN
#{table}
GROUP BY ac.owner, ac.table_name, ac.constraint_name, ac.constraint_type, ac.search_condition_vc, ac_r.table_name ) SELECT schema_name AS "schemaName", table_name AS "tableName", constraints_name AS "constraintName", constraints_type AS "constraintType", constraints_definition AS "constraintDefinition", '' AS "remarks" FROM ora_all_constraints ORDER BY schema_name, table_name, constraints_type, constraints_name

WITH ora_fk_columns AS ( /* 外部キーを構成する列。多重度の判定に用いる。 参照元テーブルが出力対象であれば判定できればよいため、ora_all_foreignkeys のようなシステムスキーマの除外は行わない */ SELECT ac.owner AS schema_name, ac.table_name AS table_name, ac.constraint_name AS foreignkey_name, acc.column_name AS column_name FROM all_constraints ac JOIN all_cons_columns acc ON acc.owner = ac.owner AND acc.constraint_name = ac.constraint_name WHERE ac.constraint_type = 'R'
AND ac.owner IN
#{schema}
), ora_unique_keys AS ( /* 一意性を保証するキーを構成する列。一意索引と、一意索引に支えられない場合がある 主キー制約・一意制約（遅延可能な制約など）の双方から収集する。 関数ベース索引や降順索引の列は SYS_NC00004$ のような内部名となり 外部キー列と一致しないため、自然と判定対象から外れる */ SELECT ai.table_owner AS schema_name, ai.table_name AS table_name, 'I:' || ai.owner || '.' || ai.index_name AS unique_key_id, aic.column_name AS column_name FROM all_indexes ai JOIN all_ind_columns aic ON aic.index_owner = ai.owner AND aic.index_name = ai.index_name WHERE ai.uniqueness = 'UNIQUE' AND ai.status NOT IN ('UNUSABLE') UNION ALL SELECT ac.owner AS schema_name, ac.table_name AS table_name, 'C:' || ac.owner || '.' || ac.constraint_name AS unique_key_id, acc.column_name AS column_name FROM all_constraints ac JOIN all_cons_columns acc ON acc.owner = ac.owner AND acc.constraint_name = ac.constraint_name WHERE ac.constraint_type IN ('P', 'U') AND ac.status = 'ENABLED' AND ac.validated = 'VALIDATED' ), ora_unique_foreignkeys AS ( /* 外部キー列が一意キーで覆われている外部キー（1件の親に対し子が高々1件となるもの）。 一意キーの列集合が外部キーの列集合に含まれていれば外部キーの値も一意となるため、 列名の一致ではなく包含関係で判定する。 一意キーの列数と、そのうち外部キー列にも現れる列数が等しいことをもって包含とみなす */ SELECT uk.schema_name AS schema_name, uk.table_name AS table_name, fkc.foreignkey_name AS foreignkey_name FROM ora_unique_keys uk JOIN ora_fk_columns fkc ON fkc.schema_name = uk.schema_name AND fkc.table_name = uk.table_name GROUP BY uk.schema_name, uk.table_name, uk.unique_key_id, fkc.foreignkey_name HAVING COUNT(DISTINCT uk.column_name) = COUNT(DISTINCT CASE WHEN uk.column_name = fkc.column_name THEN uk.column_name END) ), ora_mandatory_foreignkeys AS ( -- 外部キー列がすべてNOT NULLの外部キー（1件の子が必ず親を1件持つもの）。 -- 'N'より'Y'が大きいため、1列でもNULLを許容すると最大値は'Y'となる SELECT fkc.schema_name AS schema_name, fkc.table_name AS table_name, fkc.foreignkey_name AS foreignkey_name FROM ora_fk_columns fkc JOIN all_tab_columns atc ON atc.owner = fkc.schema_name AND atc.table_name = fkc.table_name AND atc.column_name = fkc.column_name GROUP BY fkc.schema_name, fkc.table_name, fkc.foreignkey_name HAVING MAX(atc.nullable) = 'N' ), ora_all_foreignkeys AS ( SELECT ac.constraint_name AS foreignkey_name, ac.owner AS schema_name, ac.table_name AS table_name, LISTAGG(acc.column_name, ',') WITHIN GROUP (ORDER BY acc.position) AS column_names, ac_r.owner AS reference_schema_name, ac_r.table_name AS reference_table_name, LISTAGG(acc_r.column_name, ',') WITHIN GROUP (ORDER BY acc_r.position) AS reference_column_names FROM all_constraints ac LEFT OUTER JOIN all_cons_columns acc ON ac.constraint_name = acc.constraint_name AND ac.owner = acc.owner AND ac.constraint_type = 'R' LEFT OUTER JOIN all_constraints ac_r ON ac.r_constraint_name = ac_r.constraint_name AND ac.r_owner = ac_r.owner LEFT OUTER JOIN all_cons_columns acc_r ON ac_r.constraint_name = acc_r.constraint_name AND ac_r.owner = acc_r.owner AND acc.position = acc_r.position WHERE ac.OWNER NOT IN
AND ac.owner IN
#{schema}
GROUP BY ac.constraint_name, ac.owner, ac.table_name, ac_r.owner, ac_r.table_name ORDER BY ac.constraint_name, ac.owner, ac.table_name, ac_r.owner, ac_r.table_name ) SELECT schema_name AS "schemaName", table_name AS "tableName", foreignkey_name AS "foreignKeyName", column_names AS "columnNames", reference_schema_name AS "referenceSchemaName", reference_table_name AS "referenceTableName", reference_column_names AS "referenceColumnNames", CASE WHEN EXISTS ( SELECT 1 FROM ora_unique_foreignkeys u WHERE u.schema_name = f.schema_name AND u.table_name = f.table_name AND u.foreignkey_name = f.foreignkey_name ) THEN 1 ELSE 0 END AS "childKeyUnique", CASE WHEN EXISTS ( SELECT 1 FROM ora_mandatory_foreignkeys m WHERE m.schema_name = f.schema_name AND m.table_name = f.table_name AND m.foreignkey_name = f.foreignkey_name ) THEN 1 ELSE 0 END AS "childKeyMandatory" FROM ora_all_foreignkeys f WHERE column_names IS NOT NULL ORDER BY schema_name, table_name, foreignkey_name

WITH
ora_triggers AS (
SELECT tr.table_owner AS schema_name, tr.table_name AS table_name, tr.trigger_name AS trigger_name, CASE WHEN tr.trigger_type LIKE 'BEFORE%' THEN 'BEFORE' WHEN tr.trigger_type LIKE 'AFTER%' THEN 'AFTER' ELSE tr.trigger_type END AS timing, REPLACE(TRIM(tr.triggering_event), ' OR ', '/') AS events, CASE WHEN tr.trigger_type LIKE '%EACH ROW' OR tr.trigger_type = 'INSTEAD OF' THEN 'ROW' WHEN tr.trigger_type = 'COMPOUND' THEN '' ELSE 'STATEMENT' END AS orientation, 'CREATE OR REPLACE TRIGGER ' || TRIM(REGEXP_REPLACE(tr.description, '\s+', ' ')) || CASE WHEN tr.when_clause IS NOT NULL THEN ' WHEN (' || tr.when_clause || ')' END AS trigger_definition, long_value('SELECT trigger_body FROM all_triggers WHERE owner = :p1 AND trigger_name = :p2', tr.owner, tr.trigger_name) AS body FROM all_triggers tr WHERE tr.base_object_type IN ('TABLE', 'VIEW') AND tr.table_owner NOT IN
AND tr.table_owner IN
#{schema}
) SELECT schema_name AS "schemaName", table_name AS "tableName", trigger_name AS "triggerName", timing AS "timing", events AS "events", orientation AS "orientation", '' AS "functionName", trigger_definition AS "triggerDefinition", body AS "body" FROM ora_triggers ORDER BY schema_name, table_name, trigger_name

WITH
ora_partitions AS (
SELECT tp.table_owner AS schema_name, tp.table_name AS table_name, tp.partition_name AS partition_name, tp.table_name AS parent_name, pt.partitioning_type AS partitioning_type, long_value('SELECT high_value FROM all_tab_partitions WHERE table_owner = :p1 AND table_name = :p2 AND partition_name = :p3', tp.table_owner, tp.table_name, tp.partition_name) AS high_value, CASE WHEN tp.subpartition_count > 0 THEN pt.subpartitioning_type || ' (' || ( SELECT LISTAGG(k.column_name, ', ') WITHIN GROUP (ORDER BY k.column_position) FROM all_subpart_key_columns k WHERE k.owner = tp.table_owner AND k.name = tp.table_name AND k.object_type = 'TABLE' ) || ')' ELSE '' END AS partition_key, tp.partition_position AS partition_position, 0 AS subpartition_position FROM all_tab_partitions tp JOIN all_part_tables pt ON pt.owner = tp.table_owner AND pt.table_name = tp.table_name WHERE tp.table_owner NOT IN
AND tp.table_owner IN
#{schema}
UNION ALL SELECT sp.table_owner, sp.table_name, sp.subpartition_name, sp.partition_name, pt.subpartitioning_type, long_value('SELECT high_value FROM all_tab_subpartitions WHERE table_owner = :p1 AND table_name = :p2 AND subpartition_name = :p3', sp.table_owner, sp.table_name, sp.subpartition_name), '', tp.partition_position, sp.subpartition_position FROM all_tab_subpartitions sp JOIN all_tab_partitions tp ON tp.table_owner = sp.table_owner AND tp.table_name = sp.table_name AND tp.partition_name = sp.partition_name JOIN all_part_tables pt ON pt.owner = sp.table_owner AND pt.table_name = sp.table_name WHERE sp.table_owner NOT IN
AND sp.table_owner IN
#{schema}
) SELECT schema_name AS "schemaName", table_name AS "tableName", schema_name AS "partitionSchemaName", partition_name AS "partitionName", schema_name AS "parentSchemaName", parent_name AS "parentName",
CASE WHEN partitioning_type = 'RANGE' THEN TO_CLOB('VALUES LESS THAN (') || high_value || ')' WHEN partitioning_type = 'LIST' AND DBMS_LOB.COMPARE(high_value, TO_CLOB('DEFAULT')) = 0 THEN TO_CLOB('DEFAULT') WHEN partitioning_type = 'LIST' THEN TO_CLOB('VALUES (') || high_value || ')' ELSE TO_CLOB('') END AS "bound", partition_key AS "partitionKey" FROM ora_partitions ORDER BY schema_name, table_name, partition_position, subpartition_position

WITH
ora_functions AS (
SELECT p.owner AS schema_name, p.object_name AS object_name, p.object_type AS object_type, CASE WHEN p.object_type = 'PACKAGE' THEN p.object_name || '.' || p.procedure_name ELSE p.object_name END AS function_name, p.subprogram_id AS subprogram_id, CASE WHEN p.object_type != 'PACKAGE' THEN p.object_type WHEN EXISTS ( SELECT 1 FROM all_arguments r WHERE r.object_id = p.object_id AND r.subprogram_id = p.subprogram_id AND r.position = 0 AND r.data_level = 0 ) THEN 'FUNCTION' ELSE 'PROCEDURE' END AS function_kind, ( SELECT LISTAGG( a.argument_name || CASE a.in_out WHEN 'IN' THEN '' ELSE ' ' || a.in_out END || ' ' || COALESCE(a.type_name, a.data_type), ', ') WITHIN GROUP (ORDER BY a.sequence) FROM all_arguments a WHERE a.object_id = p.object_id AND a.subprogram_id = p.subprogram_id AND a.position > 0 AND a.data_level = 0 AND a.argument_name IS NOT NULL ) AS function_arguments, ( SELECT MAX(COALESCE(r.type_name, r.data_type)) FROM all_arguments r WHERE r.object_id = p.object_id AND r.subprogram_id = p.subprogram_id AND r.position = 0 AND r.data_level = 0 ) AS function_result, ROW_NUMBER() OVER ( PARTITION BY p.owner, CASE WHEN p.object_type = 'PACKAGE' THEN p.object_name || '.' || p.procedure_name ELSE p.object_name END ORDER BY p.subprogram_id) AS overload_index, COUNT(*) OVER ( PARTITION BY p.owner, CASE WHEN p.object_type = 'PACKAGE' THEN p.object_name || '.' || p.procedure_name ELSE p.object_name END ) AS overload_count FROM all_procedures p WHERE (p.object_type IN ('FUNCTION', 'PROCEDURE') OR (p.object_type = 'PACKAGE' AND p.procedure_name IS NOT NULL)) AND p.owner NOT IN
AND p.owner IN
#{schema}
) SELECT SYS_CONTEXT('USERENV','DB_NAME') AS "dbName", schema_name AS "schemaName", function_name AS "functionName", overload_index AS "overloadIndex", overload_count AS "overloadCount", function_kind AS "functionKind", function_arguments AS "functionArguments", CASE function_kind WHEN 'PROCEDURE' THEN '' ELSE function_result END AS "functionResult", 'PL/SQL' AS "languageName", '' AS definition FROM ora_functions ORDER BY schema_name, function_name, overload_index

WITH
ora_functions AS (
SELECT p.owner AS schema_name, p.object_name AS object_name, p.object_type AS object_type, CASE WHEN p.object_type = 'PACKAGE' THEN p.object_name || '.' || p.procedure_name ELSE p.object_name END AS function_name, p.subprogram_id AS subprogram_id, CASE WHEN p.object_type != 'PACKAGE' THEN p.object_type WHEN EXISTS ( SELECT 1 FROM all_arguments r WHERE r.object_id = p.object_id AND r.subprogram_id = p.subprogram_id AND r.position = 0 AND r.data_level = 0 ) THEN 'FUNCTION' ELSE 'PROCEDURE' END AS function_kind, ( SELECT LISTAGG( a.argument_name || CASE a.in_out WHEN 'IN' THEN '' ELSE ' ' || a.in_out END || ' ' || COALESCE(a.type_name, a.data_type), ', ') WITHIN GROUP (ORDER BY a.sequence) FROM all_arguments a WHERE a.object_id = p.object_id AND a.subprogram_id = p.subprogram_id AND a.position > 0 AND a.data_level = 0 AND a.argument_name IS NOT NULL ) AS function_arguments, ( SELECT MAX(COALESCE(r.type_name, r.data_type)) FROM all_arguments r WHERE r.object_id = p.object_id AND r.subprogram_id = p.subprogram_id AND r.position = 0 AND r.data_level = 0 ) AS function_result, ROW_NUMBER() OVER ( PARTITION BY p.owner, CASE WHEN p.object_type = 'PACKAGE' THEN p.object_name || '.' || p.procedure_name ELSE p.object_name END ORDER BY p.subprogram_id) AS overload_index, COUNT(*) OVER ( PARTITION BY p.owner, CASE WHEN p.object_type = 'PACKAGE' THEN p.object_name || '.' || p.procedure_name ELSE p.object_name END ) AS overload_count FROM all_procedures p WHERE (p.object_type IN ('FUNCTION', 'PROCEDURE') OR (p.object_type = 'PACKAGE' AND p.procedure_name IS NOT NULL)) AND p.owner NOT IN
AND p.owner IN
#{schema}
) SELECT SYS_CONTEXT('USERENV','DB_NAME') AS "dbName", schema_name AS "schemaName", function_name AS "functionName", overload_index AS "overloadIndex", overload_count AS "overloadCount", function_kind AS "functionKind", function_arguments AS "functionArguments", CASE function_kind WHEN 'PROCEDURE' THEN '' ELSE function_result END AS "functionResult", 'PL/SQL' AS "languageName", CASE object_type WHEN 'PACKAGE' THEN source_text(schema_name, object_name, 'PACKAGE') || CHR(10) || CHR(10) || source_text(schema_name, object_name, 'PACKAGE BODY') ELSE source_text(schema_name, object_name, object_type) END AS definition FROM ora_functions ORDER BY schema_name, function_name, overload_index

WITH ora_types AS ( SELECT t.owner AS schema_name, t.type_name AS type_name, CASE WHEN t.typecode = 'OBJECT' THEN 'OBJECT' WHEN c.coll_type = 'TABLE' THEN 'NESTED TABLE' ELSE 'VARRAY' END AS type_category, CASE WHEN t.typecode = 'OBJECT' THEN ( SELECT LISTAGG( a.attr_name || ' ' || a.attr_type_name || CASE WHEN a.attr_type_name IN ('VARCHAR2', 'CHAR', 'NVARCHAR2', 'NCHAR', 'RAW') THEN '(' || a.length || ')' WHEN a.attr_type_name = 'NUMBER' AND a.precision IS NOT NULL THEN '(' || a.precision || ',' || a.scale || ')' ELSE '' END, ', ') WITHIN GROUP (ORDER BY a.attr_no) FROM all_type_attrs a WHERE a.owner = t.owner AND a.type_name = t.type_name ) ELSE CASE WHEN c.coll_type = 'TABLE' THEN 'TABLE' ELSE 'VARRAY(' || c.upper_bound || ')' END || ' OF ' || c.elem_type_name || CASE WHEN c.elem_type_name IN ('VARCHAR2', 'CHAR', 'NVARCHAR2', 'NCHAR', 'RAW') THEN '(' || c.length || ')' WHEN c.elem_type_name = 'NUMBER' AND c.precision IS NOT NULL THEN '(' || c.precision || ',' || c.scale || ')' ELSE '' END END AS definition FROM all_types t LEFT OUTER JOIN all_coll_types c ON c.owner = t.owner AND c.type_name = t.type_name WHERE t.typecode IN ('OBJECT', 'COLLECTION') AND t.owner NOT IN
AND t.owner IN
#{schema}
) SELECT SYS_CONTEXT('USERENV','DB_NAME') AS "dbName", schema_name AS "schemaName", type_name AS "typeName", type_category AS "typeCategory", definition AS definition FROM ora_types ORDER BY schema_name, type_name
